    r['result']='holding'
    r['holding_days_label']=f"D{v['D']}/10"
    if 'holding_days' in r and not isinstance(r['holding_days'],int): r['holding_days']=v['D']
    base=f"收盤 {v['cl']}（今日 {v['chg']:+.2f}%，相對推薦價 {v['ret']:+.2f}%）；10-01 T86 {tot:+,} 張"
